using Microsoft.AspNetCore.Mvc; using NexusTelecommunicationManagementSystem.Services;
namespace NexusTelecommunicationManagementSystem.Controllers;
public class SupportController:Controller{private readonly NexusService _nexus;public SupportController(NexusService n)=>_nexus=n;[HttpGet]public IActionResult Index(){if(HttpContext.Session.GetString("Role")!="Customer")return RedirectToAction("Login","Account");return View();}[HttpPost][ValidateAntiForgeryToken]public IActionResult Index(string name,string email,string message){if(HttpContext.Session.GetString("Role")!="Customer")return RedirectToAction("Login","Account");_nexus.CreateSupportTicket(name,email,message,HttpContext.Session.GetInt32("UserId"));TempData["SupportMessage"]="Your support request has been received. Our service team will contact you shortly.";return RedirectToAction(nameof(Index));}}
